SELECT COUNT(*) FROM (
  SELECT dropoff_zone_id FROM gold.fct_rideshare_trip WHERE is_plausible = TRUE AND pickup_at >= CAST('2026-09-26 06:00:00-04:00' AS TIMESTAMP WITH TIME ZONE) AND pickup_at < CAST('2026-10-03 06:00:00-04:00' AS TIMESTAMP WITH TIME ZONE)
  UNION ALL
  SELECT dropoff_zone_id FROM gold.fct_taxi_trip WHERE is_plausible = TRUE AND pickup_at >= CAST('2026-09-26 06:00:00-04:00' AS TIMESTAMP WITH TIME ZONE) AND pickup_at < CAST('2026-10-03 06:00:00-04:00' AS TIMESTAMP WITH TIME ZONE)
) trips JOIN gold.dim_taxi_zone tz ON trips.dropoff_zone_id = tz.zone_id WHERE tz.is_airport = TRUE;
